import{_ as t,o,c as a,a0 as d}from"./chunks/framework.DPF_EvDs.js";const u=JSON.parse('{"title":"Statuses","description":"","frontmatter":{},"headers":[],"relativePath":"Statuses.md","filePath":"Statuses.md"}'),r={name:"Statuses.md"};function s(n,e,h,c,i,l){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h1><p><em>Canonical page, with its live parts: <a href="https://neurons-me.github.io/Cleaker/docs/en/Statuses.html" target="_blank" rel="noreferrer">https://neurons-me.github.io/Cleaker/docs/en/Statuses.html</a></em></p><blockquote><p><strong>Live:</strong> every QR.me status runs in the browser on the <a href="https://neurons-me.github.io/Cleaker/docs/en/Statuses.html" target="_blank" rel="noreferrer">canonical page</a>.</p></blockquote><p>The <a href="https://neurons-me.github.io/Cleaker/" target="_blank" rel="noreferrer">Cleaker home</a> runs <code>cleaker(me, &quot;cleaker.me&quot;)</code> with an anonymous <code>.me</code> and writes what happened under the QR:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cleaker.me reachable · 73 ms · public, no who</span></span></code></pre></div><p>Read it left to right:</p><table tabindex="0"><thead><tr><th>Part</th><th>Meaning</th></tr></thead><tbody><tr><td><code>cleaker.me</code></td><td>the namespace that was resolved</td></tr><tr><td><code>reachable</code></td><td>the state of the namespace&#39;s host (below)</td></tr><tr><td><code>73 ms</code></td><td>how long <code>GET https://cleaker.me/__bootstrap</code> took, from this browser</td></tr><tr><td><code>public, no who</code></td><td>who is looking: nobody. The <code>.me</code> is anonymous, so the node can read what is public and nothing else</td></tr></tbody></table><h2 id="the-line-under-the-qr" tabindex="-1">The line under the QR <a class="header-anchor" href="#the-line-under-the-qr" aria-label="Permalink to &quot;The line under the QR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Line</th><th>QR</th><th>What happened</th></tr></thead><tbody><tr><td>loading</td><td><code>connecting to cleaker.me…</code></td><td>checking</td><td>the npm builds of <code>this.me</code> and <code>cleaker</code> are downloading and their sha256 is being checked</td></tr><tr><td>checking</td><td><code>connecting to cleaker.me…</code></td><td>checking</td><td><code>validateHosts()</code> is pinging the host</td></tr><tr><td><strong>reachable</strong></td><td><code>cleaker.me reachable · N ms · public, no who</code></td><td>confirmed</td><td><code>https://cleaker.me</code> answered <code>/__bootstrap</code></td></tr><tr><td>unreachable</td><td><code>cleaker.me did not answer</code></td><td>off</td><td>the host did not answer: a network error, or no answer within 8 s</td></tr><tr><td>error</td><td><code>could not run cleaker: …</code></td><td>error</td><td>a build failed to load, or its sha256 did not match</td></tr></tbody></table><p><strong>Reachable is not signed in.</strong> &quot;Confirmed&quot; on the QR means the namespace answered. Nothing was signed, claimed or written: the visitor has no who.</p><h2 id="how-each-status-looks" tabindex="-1">How each status looks <a class="header-anchor" href="#how-each-status-looks" aria-label="Permalink to &quot;How each status looks&quot;">​</a></h2><p>The QRs at the top of this page are the real QR.me component, drawn in this page&#39;s theme: change the theme or light / dark in the top bar and they follow it.</p><ul><li><strong><code>idle</code></strong> and <strong><code>confirmed</code></strong> keep the QR&#39;s own colour. What tells them apart is the dot at the start of the label: grey for <code>idle</code>, green for <code>confirmed</code>.</li><li><strong><code>checking</code></strong> uses the theme&#39;s warning colour.</li><li><strong><code>off</code></strong> is grey: <strong>nothing answers</strong> at this address.</li><li><strong><code>error</code></strong> uses the theme&#39;s error colour: <strong>something answered and refused</strong>, or cleaker could not run. A namespace that is simply not running is <code>off</code>, not <code>error</code>.</li></ul><p>On the home page the dot is covered by the padlock, so there <code>idle</code> and <code>confirmed</code> look the same and the line under the QR is what tells them apart.</p><p>The padlock on the QR is a different fact: the transport of the <strong>page you are on</strong> (HTTPS with a certificate the browser accepted, or not). It says nothing about the namespace.</p><h2 id="what-cleaker-keeps-underneath" tabindex="-1">What cleaker keeps underneath <a class="header-anchor" href="#what-cleaker-keeps-underneath" aria-label="Permalink to &quot;What cleaker keeps underneath&quot;">​</a></h2><p>The line is a summary. <code>node.getStatus()</code> returns the full picture, in three layers.</p><h3 id="per-host-transport" tabindex="-1">Per host: transport <a class="header-anchor" href="#per-host-transport" aria-label="Permalink to &quot;Per host: transport&quot;">​</a></h3><p>Can this host be reached at all?</p><table tabindex="0"><thead><tr><th><code>transport</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>unknown</code></td><td>not probed yet</td></tr><tr><td><code>up</code></td><td><code>GET &lt;host&gt;/__bootstrap</code> answered</td></tr><tr><td><code>down</code></td><td>it did not (<code>NETWORK_ERROR</code>)</td></tr></tbody></table><h3 id="per-host-triad-proof" tabindex="-1">Per host: triad (proof) <a class="header-anchor" href="#per-host-triad-proof" aria-label="Permalink to &quot;Per host: triad (proof)&quot;">​</a></h3><p>Did this host accept a proof from this <code>.me</code>?</p><table tabindex="0"><thead><tr><th><code>triad</code></th><th>Meaning</th><th>Typical <code>error</code></th></tr></thead><tbody><tr><td><code>verified</code></td><td>signed in: the host accepted the proof and the memories were hydrated</td><td>—</td></tr><tr><td><code>unverified</code></td><td>no proof was accepted, without anything being wrong</td><td><code>PROVE_UNSUPPORTED</code> (anonymous <code>.me</code>, no who), <code>CLAIM_NOT_FOUND</code> (the who has no claim on this namespace)</td></tr><tr><td><code>failed</code></td><td>the host refused the proof</td><td>the host&#39;s error code</td></tr><tr><td><code>skipped</code></td><td>another host already verified first (<code>first-success</code>)</td><td>—</td></tr></tbody></table><h3 id="per-node-state-and-overall" tabindex="-1">Per node: state and overall <a class="header-anchor" href="#per-node-state-and-overall" aria-label="Permalink to &quot;Per node: state and overall&quot;">​</a></h3><p><code>state</code> is where the node is in its cycle:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>idle → discovering → probing → opening → hydrating → ready</span></span>
<span class="line"><span>                                                    → degraded</span></span>
<span class="line"><span>                                                    → offline</span></span></code></pre></div><p><code>overall</code> is the verdict:</p><table tabindex="0"><thead><tr><th><code>overall</code></th><th>Meaning</th></tr></thead><tbody><tr><td><code>healthy</code></td><td>at least one host is <code>verified</code></td></tr><tr><td><code>degraded</code></td><td>hosts were tried, none is <code>verified</code></td></tr><tr><td><code>offline</code></td><td>no namespace, or no host to try</td></tr></tbody></table><h2 id="the-anonymous-visit-layer-by-layer" tabindex="-1">The anonymous visit, layer by layer <a class="header-anchor" href="#the-anonymous-visit-layer-by-layer" aria-label="Permalink to &quot;The anonymous visit, layer by layer&quot;">​</a></h2><p>For the line <code>cleaker.me reachable · 73 ms · public, no who</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://cleaker.me   transport: up     triad: unverified (PROVE_UNSUPPORTED)</span></span>
<span class="line"><span>node                 state: degraded   overall: degraded</span></span></code></pre></div><p><code>degraded</code> is cleaker&#39;s honest answer to &quot;is anyone verified here?&quot; (no), not a fault. cleaker has no <code>overall</code> state yet for <strong>public, reachable, no who</strong>, so the home page reads the host&#39;s <code>transport</code> directly and says <em>reachable</em>. A state of its own for that case is an open proposal (see <a href="./The-Model.html">The Model</a>, &quot;Where this stands&quot;).</p><h2 id="only-the-declared-host" tabindex="-1">Only the declared host <a class="header-anchor" href="#only-the-declared-host" aria-label="Permalink to &quot;Only the declared host&quot;">​</a></h2><p>cleaker&#39;s discovery also lists the page&#39;s own origin and <code>http://localhost</code> (to find the visitor&#39;s own local monad). The home page declares <code>https://cleaker.me</code> and refuses every other origin before a request exists, so a public page never probes a visitor&#39;s localhost. Those refused candidates are left out of the line.</p><p>Source: <a href="https://github.com/neurons-me/Cleaker/blob/main/assets/cleaker-live/cleaker-live.js" target="_blank" rel="noreferrer"><code>assets/cleaker-live/cleaker-live.js</code></a>.</p>`,35)])])}const b=t(r,[["render",s]]);export{u as __pageData,b as default};
